package ar.com.liftmanager.service;
import ar.com.liftmanager.dto.ApiDtos.*;import ar.com.liftmanager.model.*;import ar.com.liftmanager.repository.*;import org.springframework.stereotype.Service;import java.time.LocalDateTime;import java.util.*;
@Service public class ClaimService {
 private final ClaimRepository claims;private final ElevatorService elevatorService;private final UserRepository users;private final CurrentUserService current;private final ElevatorRepository elevatorRepo;
 public ClaimService(ClaimRepository c,ElevatorService e,UserRepository u,CurrentUserService cu,ElevatorRepository er){claims=c;elevatorService=e;users=u;current=cu;elevatorRepo=er;}
 public ClaimView create(ClaimRequest r){AppUser me=current.get();if(me.getRole()!=Role.BUILDING_MANAGER&&me.getRole()!=Role.ADMIN)throw BusinessException.forbidden("Solo administración puede registrar reclamos");Elevator e=elevatorService.get(r.elevatorId());Claim c=new Claim();c.setElevator(e);c.setCreatedBy(me);c.setTitle(r.title().trim());c.setDescription(r.description().trim());c.setPriority(r.priority());if(r.priority()==Priority.CRITICAL){e.setStatus(ElevatorStatus.OUT_OF_SERVICE);elevatorRepo.save(e);}return view(claims.save(c));}
 public List<ClaimView> list(){AppUser me=current.get();List<Claim> all=me.getRole()==Role.TECHNICIAN?claims.findByAssignedToId(me.getId()):me.getRole()==Role.BUILDING_MANAGER?(me.getBuilding()==null?List.of():claims.findByElevatorBuildingId(me.getBuilding().getId())):claims.findAll();return all.stream().sorted(Comparator.comparing(Claim::getCreatedAt).reversed()).map(this::view).toList();}
 public ClaimView assign(Long id,AssignClaimRequest r){current.requireAdmin();Claim c=claims.findById(id).orElseThrow(()->BusinessException.notFound("Reclamo no encontrado"));AppUser tech=users.findById(r.technicianId()).orElseThrow(()->BusinessException.notFound("Técnico no encontrado"));if(tech.getRole()!=Role.TECHNICIAN||!tech.isActive())throw BusinessException.badRequest("El responsable debe ser un técnico activo");if(c.getStatus()==ClaimStatus.RESOLVED||c.getStatus()==ClaimStatus.CLOSED)throw BusinessException.conflict("No se puede asignar un reclamo cerrado o resuelto");c.setAssignedTo(tech);c.setStatus(ClaimStatus.ASSIGNED);return view(claims.save(c));}
 public ClaimView status(Long id,ClaimStatusRequest r){Claim c=claims.findById(id).orElseThrow(()->BusinessException.notFound("Reclamo no encontrado"));AppUser me=current.get();if(me.getRole()!=Role.ADMIN&&(c.getAssignedTo()==null||!c.getAssignedTo().getId().equals(me.getId())))throw BusinessException.forbidden("No tenés asignado este reclamo");ClaimStatus next=r.status();boolean valid=switch(c.getStatus()){case ASSIGNED->next==ClaimStatus.IN_PROGRESS||next==ClaimStatus.CLOSED;case IN_PROGRESS->next==ClaimStatus.RESOLVED;case RESOLVED->next==ClaimStatus.CLOSED;case OPEN->false;case CLOSED->false;};if(!valid)throw BusinessException.conflict("Transición de estado no permitida");c.setStatus(next);if(next==ClaimStatus.RESOLVED)c.setResolvedAt(LocalDateTime.now());return view(claims.save(c));}
 private ClaimView view(Claim c){return new ClaimView(c.getId(),c.getElevator().getId(),c.getElevator().getCode(),c.getElevator().getBuilding().getName(),c.getCreatedBy().getId(),c.getCreatedBy().getName(),c.getAssignedTo()==null?null:c.getAssignedTo().getId(),c.getAssignedTo()==null?null:c.getAssignedTo().getName(),c.getTitle(),c.getDescription(),c.getPriority(),c.getStatus(),c.getCreatedAt(),c.getResolvedAt());}
}
